import{_ as t,c as o,o as n,ae as r}from"./chunks/framework.DCU7Csu6.js";const h=JSON.parse('{"title":"wb_daytona_sdk - Epic Breakdown","description":"","frontmatter":{"stepsCompleted":["step-01-validate-prerequisites","step-02-design-epics","step-03-create-stories","step-04-final-validation"],"inputDocuments":["backlog/tasks/task-51 through task-81 (17 To Do tasks from WB API updates)","backlog/sprint-status.yaml","docs/epics/ (47 completed EPICs for historical context)"]},"headers":[],"relativePath":"epics.md","filePath":"epics.md"}'),a={name:"epics.md"};function s(i,e,d,c,l,p){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="wb-daytona-sdk-epic-breakdown" tabindex="-1">wb_daytona_sdk - Epic Breakdown <a class="header-anchor" href="#wb-daytona-sdk-epic-breakdown" aria-label="Permalink to &quot;wb_daytona_sdk - Epic Breakdown&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This document provides the epic and story breakdown for wb_daytona_sdk Sprint Cycle Q2 2026, decomposing WB API updates (March 2026) into implementable work items organized by priority and module.</p><h2 id="requirements-inventory" tabindex="-1">Requirements Inventory <a class="header-anchor" href="#requirements-inventory" aria-label="Permalink to &quot;Requirements Inventory&quot;">​</a></h2><h3 id="functional-requirements" tabindex="-1">Functional Requirements <a class="header-anchor" href="#functional-requirements" aria-label="Permalink to &quot;Functional Requirements&quot;">​</a></h3><p>FR1: Support token-type-based rate limits — SDK must apply different rate limits for Basic/Test tokens vs Personal/Service tokens (WB enforcement date: March 30, 2026) FR2: Implement GET /api/advert/v0/bids/recommendations — return recommended bids for product cards and search clusters by campaign ID and nmId (cpm campaigns only) FR3: Implement POST /api/marketplace/v3/dbw/orders/client — return buyer info for DBW orders by order IDs FR4: Implement POST /api/analytics/v1/stocks-report/wb-warehouses — return current WB warehouse inventory with warehouseId, regionName, pagination up to 250K rows (replaces deprecated GET /api/v1/supplier/stocks, disabled June 23) FR5: Update getAdvertsV2 in Promotion module to match current WB API spec FR6: Add <code>isB2b</code> field to FBS Supply type — supplies now carry B2B flag, mixed B2B/non-B2B orders in one supply rejected since March 19 FR7: Add <code>isBoxOnPallet</code> and <code>boxTypeID</code> fields to FBW supply types for new &quot;Поштучная паллета&quot; supply type FR8: Add <code>currency</code> field to all 3 Sales Funnel v3 response types FR9: Fix <code>additionalErrors</code> type in ResponseCardCreate — must support Record&lt;string, string&gt; for vendorCode-keyed merging errors (Beauty/Household Chemicals categories) FR10: Add <code>status</code> field to CrossBorderStickerItem — &#39;awaitingTrackNumber&#39; | &#39;ready&#39; for sticker generation tracking (April 1) FR11: Add <code>tin</code> (ИНН) field to SellerInfoResponse</p><h3 id="non-functional-requirements" tabindex="-1">Non-Functional Requirements <a class="header-anchor" href="#non-functional-requirements" aria-label="Permalink to &quot;Non-Functional Requirements&quot;">​</a></h3><p>NFR1: All type changes must pass <code>npm run type-check</code> with zero errors NFR2: All existing 2041 tests must continue passing after changes NFR3: New methods must have unit tests covering success, error propagation, payload verification NFR4: Documentation guides must be bilingual (EN + RU) and build successfully with VitePress NFR5: JSDoc must include rate limit tables, @throws, @example, @see links to WB docs</p><h3 id="additional-requirements" tabindex="-1">Additional Requirements <a class="header-anchor" href="#additional-requirements" aria-label="Permalink to &quot;Additional Requirements&quot;">​</a></h3><ul><li>DBS deliverBulk() must document 409 ImeiIsNotFilled error and requiredMeta check workflow</li><li>User Management JSDoc must document Personal Token (category: Users) requirement and global availability</li><li>Third-party services can avoid Basic token reduced limits via traffic identification (<a href="mailto:business-solutions@rwb.ru" target="_blank" rel="noreferrer">business-solutions@rwb.ru</a>)</li><li>Deprecated GET /api/v1/supplier/stocks endpoint must be marked @deprecated with migration guidance to new wb-warehouses method</li><li>GitHub Pages guides needed for: Sales Funnel Analytics, Customer Communication, Search Queries Analytics, Seller Analytics CSV</li></ul><h3 id="fr-coverage-map" tabindex="-1">FR Coverage Map <a class="header-anchor" href="#fr-coverage-map" aria-label="Permalink to &quot;FR Coverage Map&quot;">​</a></h3><table tabindex="0"><thead><tr><th>FR</th><th>Epic</th><th>Description</th></tr></thead><tbody><tr><td>FR1</td><td>Epic 1</td><td>Token-type rate limits (Phase A: awareness, Phase B: configs)</td></tr><tr><td>FR2</td><td>Epic 2</td><td>Bids recommendations for promotion campaigns</td></tr><tr><td>FR3</td><td>Epic 3</td><td>DBW buyer info endpoint</td></tr><tr><td>FR4</td><td>Epic 4</td><td>WB warehouses current inventory</td></tr><tr><td>FR5</td><td>Epic 2</td><td>getAdvertsV2 update</td></tr><tr><td>FR6</td><td>Epic 3</td><td>isB2b flag on FBS Supply</td></tr><tr><td>FR7</td><td>Epic 3</td><td>isBoxOnPallet + boxTypeID on FBW supply types</td></tr><tr><td>FR8</td><td>Epic 5</td><td>currency field in Sales Funnel responses</td></tr><tr><td>FR9</td><td>Epic 5</td><td>additionalErrors type fix for merging errors</td></tr><tr><td>FR10</td><td>Epic 5</td><td>CrossBorder sticker generation status</td></tr><tr><td>FR11</td><td>Epic 5</td><td>tin (ИНН) in SellerInfoResponse</td></tr><tr><td>NFR1-5</td><td>All</td><td>Cross-cutting quality gates</td></tr><tr><td>Additional</td><td>Epic 5/6</td><td>JSDoc updates (IMEI, tokens), docs guides</td></tr></tbody></table><h2 id="epic-list" tabindex="-1">Epic List <a class="header-anchor" href="#epic-list" aria-label="Permalink to &quot;Epic List&quot;">​</a></h2><h3 id="epic-1-rate-limit-intelligence-by-token-type" tabindex="-1">Epic 1: Rate Limit Intelligence by Token Type <a class="header-anchor" href="#epic-1-rate-limit-intelligence-by-token-type" aria-label="Permalink to &quot;Epic 1: Rate Limit Intelligence by Token Type&quot;">​</a></h3><p>SDK consumers can configure their token type and get correct rate limiting automatically, avoiding 429 errors on Basic/Test tokens. <strong>FRs covered:</strong> FR1 <strong>Backlog tasks:</strong> task-77 <strong>Release:</strong> Phase A in v3.4.0, Phase B in v3.5.0 <strong>Implementation:</strong> Phase A = SDKConfig.tokenType + init warning; Phase B = category-level multipliers</p><h3 id="epic-2-promotion-analytics-—-bid-recommendations" tabindex="-1">Epic 2: Promotion Analytics — Bid Recommendations <a class="header-anchor" href="#epic-2-promotion-analytics-—-bid-recommendations" aria-label="Permalink to &quot;Epic 2: Promotion Analytics — Bid Recommendations&quot;">​</a></h3><p>SDK consumers can fetch recommended competitive and leader bids for campaigns and access updated campaign info, optimizing ad spend. <strong>FRs covered:</strong> FR2, FR5 <strong>Backlog tasks:</strong> task-51, task-66</p><h3 id="epic-3-order-management-enhancements-fbw-fbs" tabindex="-1">Epic 3: Order Management Enhancements (FBW/FBS) <a class="header-anchor" href="#epic-3-order-management-enhancements-fbw-fbs" aria-label="Permalink to &quot;Epic 3: Order Management Enhancements (FBW/FBS)&quot;">​</a></h3><p>SDK consumers can retrieve DBW buyer info, track B2B supply segregation, and work with new supply types (Поштучная паллета). <strong>FRs covered:</strong> FR3, FR6, FR7 <strong>Backlog tasks:</strong> task-71, task-75, task-72</p><h3 id="epic-4-inventory-stock-analytics" tabindex="-1">Epic 4: Inventory &amp; Stock Analytics <a class="header-anchor" href="#epic-4-inventory-stock-analytics" aria-label="Permalink to &quot;Epic 4: Inventory &amp; Stock Analytics&quot;">​</a></h3><p>SDK consumers can query current WB warehouse inventory with full warehouse/region data and pagination up to 250K rows, replacing the deprecated stocks endpoint. <strong>FRs covered:</strong> FR4 <strong>Backlog tasks:</strong> task-79</p><h3 id="epic-5-type-safety-api-compliance" tabindex="-1">Epic 5: Type Safety &amp; API Compliance <a class="header-anchor" href="#epic-5-type-safety-api-compliance" aria-label="Permalink to &quot;Epic 5: Type Safety &amp; API Compliance&quot;">​</a></h3><p>SDK consumers get accurate TypeScript types reflecting latest WB API responses, ensuring correct autocomplete and type checking across all modules. <strong>FRs covered:</strong> FR8, FR9, FR10, FR11 + Additional (JSDoc: IMEI, tokens) <strong>Backlog tasks:</strong> task-67, task-68, task-73, task-74, task-78, task-80</p><h3 id="epic-6-developer-documentation-guides" tabindex="-1">Epic 6: Developer Documentation Guides <a class="header-anchor" href="#epic-6-developer-documentation-guides" aria-label="Permalink to &quot;Epic 6: Developer Documentation Guides&quot;">​</a></h3><p>SDK consumers (ERP/analytics developers) get comprehensive bilingual guides for Sales Funnel, Search Queries, Customer Communication, and CSV Reports with working code examples and workflow diagrams. <strong>FRs covered:</strong> Additional Requirements (docs guides) <strong>Backlog tasks:</strong> task-69, task-70, task-76, task-81 <strong>Note:</strong> Sidebar reorganization with collapsible Analytics/Communication subsections</p><hr><h2 id="epic-1-rate-limit-intelligence-by-token-type-1" tabindex="-1">Epic 1: Rate Limit Intelligence by Token Type <a class="header-anchor" href="#epic-1-rate-limit-intelligence-by-token-type-1" aria-label="Permalink to &quot;Epic 1: Rate Limit Intelligence by Token Type&quot;">​</a></h2><p>SDK consumers can configure their token type and get correct rate limiting automatically, avoiding 429 errors on Basic/Test tokens.</p><h3 id="story-1-1-token-type-configuration" tabindex="-1">Story 1.1: Token Type Configuration <a class="header-anchor" href="#story-1-1-token-type-configuration" aria-label="Permalink to &quot;Story 1.1: Token Type Configuration&quot;">​</a></h3><p>As an SDK consumer, I want to specify my WB token type when initializing the SDK, So that the SDK can apply appropriate rate limits for my token type.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> a developer initializes WildberriesSDK with <code>tokenType: &#39;basic&#39;</code><strong>When</strong> the SDK is created <strong>Then</strong> the <code>tokenType</code> is stored in config and accessible internally <strong>And</strong> a warning is logged: &quot;Basic token detected. Reduced rate limits apply. Consider upgrading to Personal or Service token.&quot;</p><p><strong>Given</strong> a developer initializes WildberriesSDK without <code>tokenType</code><strong>When</strong> the SDK is created <strong>Then</strong> the default <code>tokenType</code> is <code>&#39;personal&#39;</code> (no warning logged)</p><h3 id="story-1-2-reduced-rate-limits-for-basic-test-tokens" tabindex="-1">Story 1.2: Reduced Rate Limits for Basic/Test Tokens <a class="header-anchor" href="#story-1-2-reduced-rate-limits-for-basic-test-tokens" aria-label="Permalink to &quot;Story 1.2: Reduced Rate Limits for Basic/Test Tokens&quot;">​</a></h3><p>As an SDK consumer using a Basic or Test token, I want the SDK to automatically apply correct reduced rate limits, So that I don&#39;t hit 429 errors from exceeding WB&#39;s token-specific quotas.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> SDK is initialized with <code>tokenType: &#39;basic&#39;</code> or <code>&#39;test&#39;</code><strong>When</strong> the rate limiter loads configs <strong>Then</strong> category-level multipliers reduce limits (e.g., general: 0.001, orders: 0.003, analytics: 0.05) <strong>And</strong> burst limits are set to 1 for all endpoints</p><p><strong>Given</strong> SDK is initialized with <code>tokenType: &#39;personal&#39;</code> or <code>&#39;service&#39;</code><strong>When</strong> the rate limiter loads configs <strong>Then</strong> standard rate limits are applied (no reduction)</p><h3 id="story-1-3-token-type-documentation-guide" tabindex="-1">Story 1.3: Token Type Documentation Guide <a class="header-anchor" href="#story-1-3-token-type-documentation-guide" aria-label="Permalink to &quot;Story 1.3: Token Type Documentation Guide&quot;">​</a></h3><p>As an SDK consumer, I want to understand WB token types, their rate limits, and migration recommendations, So that I can choose the right token for my integration.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> the docs site <strong>When</strong> a user navigates to the Configuration guide <strong>Then</strong> they find a &quot;Token Types &amp; Rate Limits&quot; section explaining 4 token types, their limits, and recommendations <strong>And</strong> third-party services see the traffic identification option (<a href="mailto:business-solutions@rwb.ru" target="_blank" rel="noreferrer">business-solutions@rwb.ru</a>)</p><hr><h2 id="epic-2-promotion-analytics-—-bid-recommendations-1" tabindex="-1">Epic 2: Promotion Analytics — Bid Recommendations <a class="header-anchor" href="#epic-2-promotion-analytics-—-bid-recommendations-1" aria-label="Permalink to &quot;Epic 2: Promotion Analytics — Bid Recommendations&quot;">​</a></h2><p>SDK consumers can fetch recommended competitive and leader bids for campaigns and access updated campaign info, optimizing ad spend.</p><h3 id="story-2-1-update-getadvertsv2-method" tabindex="-1">Story 2.1: Update getAdvertsV2 Method <a class="header-anchor" href="#story-2-1-update-getadvertsv2-method" aria-label="Permalink to &quot;Story 2.1: Update getAdvertsV2 Method&quot;">​</a></h3><p>As an SDK consumer, I want the getAdvertsV2 method to match the current WB API specification, So that I get accurate campaign data with all current fields.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> the current WB API spec for GET /api/advert/v2/adverts <strong>When</strong> the developer calls <code>sdk.promotion.getAdvertsV2()</code><strong>Then</strong> the request and response types match the latest WB API schema <strong>And</strong> all new/changed fields are correctly typed <strong>And</strong> unit tests verify correct URL, params, and rateLimitKey</p><h3 id="story-2-2-implement-bid-recommendations-method" tabindex="-1">Story 2.2: Implement Bid Recommendations Method <a class="header-anchor" href="#story-2-2-implement-bid-recommendations-method" aria-label="Permalink to &quot;Story 2.2: Implement Bid Recommendations Method&quot;">​</a></h3><p>As an SDK consumer running cpm promotion campaigns, I want to fetch recommended competitive and leader bids for my product cards and search clusters, So that I can optimize my ad spend with data-driven bidding.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> a valid campaign ID and nmId belonging to a cpm campaign <strong>When</strong> the developer calls <code>sdk.promotion.getBidsRecommendations({ advertId, nmId })</code><strong>Then</strong> the response contains <code>normQueries[]</code> with <code>reachMin</code>, <code>reachMedium</code>, <code>reachMax</code> (each with <code>bidKopecks</code>) <strong>And</strong> the response may contain <code>base</code> with <code>competitiveBid</code>, <code>leadersBid</code>, <code>top2</code></p><p><strong>Given</strong> an invalid advertId or nmId not belonging to the campaign <strong>When</strong> the developer calls <code>getBidsRecommendations()</code><strong>Then</strong> a <code>ValidationError</code> is thrown with descriptive message</p><p><strong>Given</strong> the rate limit config <strong>When</strong> the method is called <strong>Then</strong> it uses rateLimitKey <code>promotion.getBidsRecommendations</code> with 5 req/min, 12s interval, burst 5</p><hr><h2 id="epic-3-order-management-enhancements-fbw-fbs-1" tabindex="-1">Epic 3: Order Management Enhancements (FBW/FBS) <a class="header-anchor" href="#epic-3-order-management-enhancements-fbw-fbs-1" aria-label="Permalink to &quot;Epic 3: Order Management Enhancements (FBW/FBS)&quot;">​</a></h2><p>SDK consumers can retrieve DBW buyer info, track B2B supply segregation, and work with new supply types (Поштучная паллета).</p><h3 id="story-3-1-implement-dbw-buyer-info-method" tabindex="-1">Story 3.1: Implement DBW Buyer Info Method <a class="header-anchor" href="#story-3-1-implement-dbw-buyer-info-method" aria-label="Permalink to &quot;Story 3.1: Implement DBW Buyer Info Method&quot;">​</a></h3><p>As an SDK consumer fulfilling DBW orders, I want to retrieve buyer information by order IDs, So that I can process deliveries with correct customer data.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> an array of valid DBW order IDs <strong>When</strong> the developer calls <code>sdk.ordersFBW.getClientInfo([orderId1, orderId2])</code><strong>Then</strong> the response contains <code>orders[]</code> with <code>orderID</code>, <code>firstName</code>, <code>phone</code>, <code>phoneCode</code> per order</p><p><strong>Given</strong> an empty orderIds array <strong>When</strong> the developer calls <code>getClientInfo([])</code><strong>Then</strong> a <code>ValidationError</code> is thrown</p><p><strong>Given</strong> the endpoint URL <strong>When</strong> the method sends the request <strong>Then</strong> it POSTs to <code>https://marketplace-api.wildberries.ru/api/marketplace/v3/dbw/orders/client</code></p><h3 id="story-3-2-add-b2b-flag-to-fbs-supply-type" tabindex="-1">Story 3.2: Add B2B Flag to FBS Supply Type <a class="header-anchor" href="#story-3-2-add-b2b-flag-to-fbs-supply-type" aria-label="Permalink to &quot;Story 3.2: Add B2B Flag to FBS Supply Type&quot;">​</a></h3><p>As an SDK consumer managing FBS supplies, I want to see the B2B flag on supplies and understand the B2B segregation rule, So that I can correctly group B2B and non-B2B orders into separate supplies.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> the <code>Supply</code> interface in <code>orders-fbs.types.ts</code><strong>When</strong> the developer reads a supply from <code>listSupplies()</code> or <code>getSupply()</code><strong>Then</strong> the response includes <code>isB2b?: boolean</code> indicating the supply&#39;s B2B status</p><p><strong>Given</strong> JSDoc for <code>addOrdersToSupply()</code><strong>When</strong> the developer reads the documentation <strong>Then</strong> they see a warning: mixing B2B and non-B2B orders in one supply is rejected since March 19</p><h3 id="story-3-3-add-box-on-pallet-and-boxtypeid-to-fbw-supply-types" tabindex="-1">Story 3.3: Add Box-on-Pallet and BoxTypeID to FBW Supply Types <a class="header-anchor" href="#story-3-3-add-box-on-pallet-and-boxtypeid-to-fbw-supply-types" aria-label="Permalink to &quot;Story 3.3: Add Box-on-Pallet and BoxTypeID to FBW Supply Types&quot;">​</a></h3><p>As an SDK consumer managing FBW supplies, I want to see the new &quot;Поштучная паллета&quot; supply type availability and boxTypeID in supply responses, So that I can correctly plan and track supply types.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> <code>ModelsOptionsResultModel.result[].warehouses[]</code><strong>When</strong> the developer reads acceptance options <strong>Then</strong> the response includes <code>canBoxOnPallet?: boolean</code></p><p><strong>Given</strong> <code>ModelsSupply</code> (supply list) <strong>When</strong> the developer lists supplies <strong>Then</strong> the response includes <code>boxTypeID?: number</code> and <code>isBoxOnPallet?: boolean</code></p><p><strong>Given</strong> <code>ModelsSupplyDetails</code> (supply details) <strong>When</strong> the developer gets supply details <strong>Then</strong> the response includes <code>isBoxOnPallet?: boolean</code></p><hr><h2 id="epic-4-inventory-stock-analytics-1" tabindex="-1">Epic 4: Inventory &amp; Stock Analytics <a class="header-anchor" href="#epic-4-inventory-stock-analytics-1" aria-label="Permalink to &quot;Epic 4: Inventory &amp; Stock Analytics&quot;">​</a></h2><p>SDK consumers can query current WB warehouse inventory with full warehouse/region data and pagination up to 250K rows, replacing the deprecated stocks endpoint.</p><h3 id="story-4-1-implement-wb-warehouses-stock-method-deprecate-legacy" tabindex="-1">Story 4.1: Implement WB Warehouses Stock Method &amp; Deprecate Legacy <a class="header-anchor" href="#story-4-1-implement-wb-warehouses-stock-method-deprecate-legacy" aria-label="Permalink to &quot;Story 4.1: Implement WB Warehouses Stock Method &amp; Deprecate Legacy&quot;">​</a></h3><p>As an SDK consumer (ERP/analytics service), I want to query current WB warehouse inventory with warehouse IDs, region names, and pagination, So that I can monitor stock levels across all warehouses in real time.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> optional filter params (nmIds, chrtIds, limit up to 250000, offset) <strong>When</strong> the developer calls <code>sdk.analytics.getWbWarehousesStock(params)</code><strong>Then</strong> the response contains <code>data.items[]</code> with <code>nmId</code>, <code>chrtId</code>, <code>warehouseId</code>, <code>warehouseName</code>, <code>regionName</code>, <code>quantity</code>, <code>inWayToClient</code>, <code>inWayFromClient</code></p><p><strong>Given</strong> the rate limit config <strong>When</strong> the method is called <strong>Then</strong> it uses 3 req/min, 20s interval, burst 1</p><p><strong>Given</strong> the response has more items than <code>limit</code><strong>When</strong> the developer uses offset pagination <strong>Then</strong> subsequent calls return the next page of results sorted by nmId ascending</p><p><strong>Given</strong> any existing method wrapping <code>GET /api/v1/supplier/stocks</code><strong>When</strong> the developer reads its JSDoc <strong>Then</strong> they see <code>@deprecated</code> with message: &quot;Will be disabled June 23, 2026. Use <code>getWbWarehousesStock()</code> instead.&quot;</p><p><strong>Given</strong> the analytics module documentation <strong>When</strong> the developer reads docs/modules/analytics.md <strong>Then</strong> they find a migration guide section from old to new stocks endpoint</p><hr><h2 id="epic-5-type-safety-api-compliance-1" tabindex="-1">Epic 5: Type Safety &amp; API Compliance <a class="header-anchor" href="#epic-5-type-safety-api-compliance-1" aria-label="Permalink to &quot;Epic 5: Type Safety &amp; API Compliance&quot;">​</a></h2><p>SDK consumers get accurate TypeScript types reflecting latest WB API responses, ensuring correct autocomplete and type checking across all modules.</p><h3 id="story-5-1-batch-type-alignment-sprint" tabindex="-1">Story 5.1: Batch Type Alignment Sprint <a class="header-anchor" href="#story-5-1-batch-type-alignment-sprint" aria-label="Permalink to &quot;Story 5.1: Batch Type Alignment Sprint&quot;">​</a></h3><p>As an SDK consumer, I want all TypeScript types to accurately reflect the current WB API responses, So that I get correct autocomplete, type checking, and no runtime surprises.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> <code>ResponseCardCreate.additionalErrors</code> (task-67) <strong>When</strong> WB returns vendorCode-keyed merging errors for Beauty/Household Chemicals <strong>Then</strong> the type is <code>Record&lt;string, string&gt; | string | { error: string }</code></p><p><strong>Given</strong> <code>SalesFunnelProductsResponse</code>, <code>SalesFunnelProductsHistoryResponse</code>, <code>SalesFunnelGroupedHistoryResponse</code> (task-68) <strong>When</strong> the API returns currency information <strong>Then</strong> each type includes <code>currency?: string</code></p><p><strong>Given</strong> <code>CrossBorderStickerItem</code> (task-80) <strong>When</strong> sticker generation is in progress <strong>Then</strong> the type includes <code>status?: &#39;awaitingTrackNumber&#39; | &#39;ready&#39;</code></p><p><strong>Given</strong> <code>SellerInfoResponse</code> (task-78) <strong>When</strong> the API returns seller ИНН <strong>Then</strong> the type includes <code>tin?: string</code></p><p><strong>Given</strong> <code>deliverBulk()</code> JSDoc (task-73) <strong>When</strong> developer reads the method docs <strong>Then</strong> they see <code>@throws</code> for 409 ImeiIsNotFilled and requiredMeta check workflow</p><p><strong>Given</strong> User Management methods JSDoc (task-74) <strong>When</strong> developer reads createInvite/getUsers/updateUserAccess/deleteUser docs <strong>Then</strong> they see Personal Token (category: Users) requirement and global availability note</p><hr><h2 id="epic-6-developer-documentation-guides-1" tabindex="-1">Epic 6: Developer Documentation Guides <a class="header-anchor" href="#epic-6-developer-documentation-guides-1" aria-label="Permalink to &quot;Epic 6: Developer Documentation Guides&quot;">​</a></h2><p>SDK consumers (ERP/analytics developers) get comprehensive bilingual guides for Sales Funnel, Search Queries, Customer Communication, and CSV Reports with working code examples and workflow diagrams.</p><h3 id="story-6-1-sales-funnel-analytics-guide-en-ru" tabindex="-1">Story 6.1: Sales Funnel Analytics Guide (EN+RU) <a class="header-anchor" href="#story-6-1-sales-funnel-analytics-guide-en-ru" aria-label="Permalink to &quot;Story 6.1: Sales Funnel Analytics Guide (EN+RU)&quot;">​</a></h3><p>As an SDK consumer building analytics dashboards, I want a comprehensive guide on Sales Funnel methods with code examples, So that I can implement funnel analysis using the SDK.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> the docs site <strong>When</strong> the user navigates to guides <strong>Then</strong> they find &quot;Sales Funnel Analytics&quot; covering 3 methods, filtering, metrics, practical scenarios <strong>And</strong> the guide exists in both EN and RU <strong>And</strong> VitePress sidebar has the entry under a collapsible &quot;Analytics Guides&quot; subsection</p><h3 id="story-6-2-customer-communication-guide-en-ru" tabindex="-1">Story 6.2: Customer Communication Guide (EN+RU) <a class="header-anchor" href="#story-6-2-customer-communication-guide-en-ru" aria-label="Permalink to &quot;Story 6.2: Customer Communication Guide (EN+RU)&quot;">​</a></h3><p>As an SDK consumer building customer support tools, I want a guide covering Questions, Reviews, Chats, and Returns workflows, So that I can automate customer interaction handling.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> the docs site <strong>When</strong> the user navigates to guides <strong>Then</strong> they find &quot;Customer Communication&quot; covering all 25 methods across 5 sections with code examples <strong>And</strong> practical scenarios: polling, bulk responses, negative review workflow, CRM integration <strong>And</strong> the guide exists in EN and RU</p><h3 id="story-6-3-search-queries-analytics-guide-en-ru" tabindex="-1">Story 6.3: Search Queries Analytics Guide (EN+RU) <a class="header-anchor" href="#story-6-3-search-queries-analytics-guide-en-ru" aria-label="Permalink to &quot;Story 6.3: Search Queries Analytics Guide (EN+RU)&quot;">​</a></h3><p>As an SDK consumer optimizing product SEO, I want a guide on search query analytics with Jam subscription context, So that I can analyze search positions and keyword performance.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> the docs site <strong>When</strong> the user navigates to guides <strong>Then</strong> they find &quot;Search Queries Analytics&quot; covering 5 methods, Jam limits, SEO scenarios <strong>And</strong> cross-links to Jam subscription guide <strong>And</strong> the guide exists in EN and RU</p><h3 id="story-6-4-seller-analytics-csv-guide-en-ru" tabindex="-1">Story 6.4: Seller Analytics CSV Guide (EN+RU) <a class="header-anchor" href="#story-6-4-seller-analytics-csv-guide-en-ru" aria-label="Permalink to &quot;Story 6.4: Seller Analytics CSV Guide (EN+RU)&quot;">​</a></h3><p>As an SDK consumer generating long-term reports, I want a guide on CSV report workflows with polling patterns, So that I can automate report generation and download.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> the docs site <strong>When</strong> the user navigates to guides <strong>Then</strong> they find &quot;Seller Analytics CSV&quot; covering 4 methods, 3-step workflow, report types, Jam requirement <strong>And</strong> the guide exists in EN and RU</p><hr><h1 id="sprint-5-6-epics-v3-5-0-—-april-2026" tabindex="-1">Sprint 5-6 Epics (v3.5.0 — April 2026) <a class="header-anchor" href="#sprint-5-6-epics-v3-5-0-—-april-2026" aria-label="Permalink to &quot;Sprint 5-6 Epics (v3.5.0 — April 2026)&quot;">​</a></h1><h2 id="epic-7-fbs-metadata-validation-deprecation" tabindex="-1">Epic 7: FBS Metadata Validation &amp; Deprecation <a class="header-anchor" href="#epic-7-fbs-metadata-validation-deprecation" aria-label="Permalink to &quot;Epic 7: FBS Metadata Validation &amp; Deprecation&quot;">​</a></h2><p>SDK consumers get accurate metadata validation feedback when delivering FBS supplies, with migration path from deprecated <code>meta</code> to <code>metaDetails</code>.</p><h3 id="story-7-1-add-metadetails-field-and-deliver-409-validation" tabindex="-1">Story 7.1: Add metaDetails Field and Deliver 409 Validation <a class="header-anchor" href="#story-7-1-add-metadetails-field-and-deliver-409-validation" aria-label="Permalink to &quot;Story 7.1: Add metaDetails Field and Deliver 409 Validation&quot;">​</a></h3><p>As an SDK consumer managing FBS supplies, I want to see metaDetails for each order and understand delivery validation errors, so that I can fix metadata issues before they block supply delivery.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> FBS order types in orders-fbs.types.ts <strong>When</strong> API returns metaDetails array <strong>Then</strong> the type includes metaDetails with validation status per metadata type</p><p><strong>Given</strong> a call to <code>updateSuppliesDeliver(supplyId)</code><strong>When</strong> metadata is invalid (IMEI since Mar 31, UIN since Apr 7, marking code since Apr 9) <strong>Then</strong> a 409 error is returned with details of which metadata failed validation</p><p><strong>Given</strong> the <code>meta</code> object in order responses <strong>When</strong> developer reads JSDoc <strong>Then</strong> they see <code>@deprecated</code> with &quot;Will be removed April 30, 2026. Use metaDetails instead.&quot;</p><hr><h2 id="epic-8-seller-information-expansion" tabindex="-1">Epic 8: Seller Information Expansion <a class="header-anchor" href="#epic-8-seller-information-expansion" aria-label="Permalink to &quot;Epic 8: Seller Information Expansion&quot;">​</a></h2><p>SDK consumers can query Jam subscription details directly and retrieve seller rating/reviews without workarounds.</p><h3 id="story-8-1-implement-jam-subscription-direct-api" tabindex="-1">Story 8.1: Implement Jam Subscription Direct API <a class="header-anchor" href="#story-8-1-implement-jam-subscription-direct-api" aria-label="Permalink to &quot;Story 8.1: Implement Jam Subscription Direct API&quot;">​</a></h3><p>As an SDK consumer, I want to get Jam subscription details via a direct API call, so that I don&#39;t need probe-based detection consuming analytics quota.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> a valid Service token of any category <strong>When</strong> the developer calls <code>sdk.general.getJamSubscription()</code><strong>Then</strong> the response includes activation date, expiration date, subscription level, method, and active status</p><p><strong>Given</strong> the existing <code>getJamSubscriptionStatus()</code> method <strong>When</strong> developer reads its JSDoc <strong>Then</strong> they see <code>@deprecated</code> recommending <code>getJamSubscription()</code> instead</p><p><strong>Given</strong> docs/guides/jam-subscription.md <strong>When</strong> a user reads the guide <strong>Then</strong> the new direct API is presented as the primary method</p><h3 id="story-8-2-implement-seller-rating-method" tabindex="-1">Story 8.2: Implement Seller Rating Method <a class="header-anchor" href="#story-8-2-implement-seller-rating-method" aria-label="Permalink to &quot;Story 8.2: Implement Seller Rating Method&quot;">​</a></h3><p>As an SDK consumer, I want to get the seller&#39;s user rating and review count, so that I can display reputation data in my dashboard.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> a Service token with &quot;Feedbacks and Questions&quot; category <strong>When</strong> the developer calls <code>sdk.general.getSellerRating()</code><strong>Then</strong> the response includes seller rating and review count</p><p><strong>Given</strong> the rate limit config <strong>When</strong> the method is called <strong>Then</strong> it uses the correct rateLimitKey</p><hr><h2 id="epic-9-rate-limit-intelligence-phase-b" tabindex="-1">Epic 9: Rate Limit Intelligence Phase B <a class="header-anchor" href="#epic-9-rate-limit-intelligence-phase-b" aria-label="Permalink to &quot;Epic 9: Rate Limit Intelligence Phase B&quot;">​</a></h2><p>SDK consumers on Basic/Test tokens get correct rate limiting automatically via category-level multipliers.</p><h3 id="story-9-1-implement-category-level-rate-limit-multipliers" tabindex="-1">Story 9.1: Implement Category-Level Rate Limit Multipliers <a class="header-anchor" href="#story-9-1-implement-category-level-rate-limit-multipliers" aria-label="Permalink to &quot;Story 9.1: Implement Category-Level Rate Limit Multipliers&quot;">​</a></h3><p>As an SDK consumer using a Basic or Test token, I want the SDK to apply correct reduced rate limits per API category, so that I don&#39;t hit 429 errors from exceeding WB&#39;s token-specific quotas.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> SDK initialized with <code>tokenType: &#39;basic&#39;</code> or <code>&#39;test&#39;</code><strong>When</strong> the rate limiter applies limits <strong>Then</strong> category-level multipliers reduce limits (e.g., general: 0.001, orders: 0.003, analytics: 0.05) <strong>And</strong> burst limits are set to 1 for all endpoints</p><p><strong>Given</strong> SDK initialized with <code>tokenType: &#39;personal&#39;</code> or <code>&#39;service&#39;</code><strong>When</strong> the rate limiter applies limits <strong>Then</strong> standard rate limits are unchanged</p><p><strong>Given</strong> the configuration guide <strong>When</strong> a developer reads token type documentation <strong>Then</strong> they find rate limit tables per category for Basic/Test tokens <strong>And</strong> traffic identification info for third-party services (<a href="mailto:business-solutions@rwb.ru" target="_blank" rel="noreferrer">business-solutions@rwb.ru</a>)</p><hr><h2 id="epic-10-api-compliance-housekeeping" tabindex="-1">Epic 10: API Compliance Housekeeping <a class="header-anchor" href="#epic-10-api-compliance-housekeeping" aria-label="Permalink to &quot;Epic 10: API Compliance Housekeeping&quot;">​</a></h2><p>SDK types stay accurate with latest WB API changes.</p><h3 id="story-10-1-batch-type-and-jsdoc-fixes-april" tabindex="-1">Story 10.1: Batch Type and JSDoc Fixes (April) <a class="header-anchor" href="#story-10-1-batch-type-and-jsdoc-fixes-april" aria-label="Permalink to &quot;Story 10.1: Batch Type and JSDoc Fixes (April)&quot;">​</a></h3><p>As an SDK consumer, I want types to reflect latest WB API behavior, so that I get correct autocomplete and no runtime surprises.</p><p><strong>Acceptance Criteria:</strong></p><p><strong>Given</strong> normquery/stats response for cpc campaigns <strong>When</strong> views, ctr, cpm are absent <strong>Then</strong> these fields are typed as optional in <code>V0GetNormQueryStatsItemStat</code></p><p><strong>Given</strong> product cards error list response <strong>When</strong> API returns updatedAt per batch item <strong>Then</strong> <code>ModelsErrorTableListPublicRespV2Item</code> includes <code>updatedAt?: string</code></p>',158)])])}const u=t(a,[["render",s]]);export{h as __pageData,u as default};
